double GetBoxVolume(const BoundingBox3D& box) {
    double dx = box.Max.x - box.Min.x;
    double dy = box.Max.y - box.Min.y;
    double dz = box.Max.z - box.Min.z;

    if (dx <= 0.0 || dy <= 0.0 || dz <= 0.0)
        return 0.0;

    return dx * dy * dz;
}

